-- Fresh demo database only. Create the six Auth users first.
BEGIN;
DO $$ BEGIN
IF (SELECT count(*) FROM auth.users WHERE lower(email) IN ('owner@example.com','admin@example.com','salesman.a@example.com','salesman.b@example.com','production@example.com','accountant@example.com')) <> 6 THEN RAISE EXCEPTION 'Create all six demo Auth users first'; END IF;
IF EXISTS (SELECT 1 FROM public.products) OR EXISTS (SELECT 1 FROM public.stock_movements) THEN RAISE EXCEPTION 'Seed already loaded or database not empty; no changes made'; END IF;
END $$;
